import{_ as r,C as s,o as e,c as n,a2 as l,b as i,w as a,a as d,E,a3 as A}from"./chunks/framework.BBdhqAg0.js";const g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",f=JSON.parse('{"title":"통합 검색 (Search)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/search.md","filePath":"work-manage/search.md","lastUpdated":1793417412000}'),C={name:"work-manage/search.md"};function c(B,t,h,u,m,p){const o=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="통합-검색-search" tabindex="-1">통합 검색 (Search) <a class="header-anchor" href="#통합-검색-search" aria-label="Permalink to &quot;통합 검색 (Search)&quot;">​</a></h1><blockquote><p><strong>통합 검색</strong>은 업무관리시스템의 모든 워크스페이스와 핵심 모듈(회의록, 업무, 댓글, 공지, 문서, 게시판)에 분산된 방대한 데이터를 키워드 하나로 신속하게 찾아내는 <strong>전사 크로스 도메인 검색 엔진</strong>입니다.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+g+'" alt="통합 검색 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/search.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="_1-개요-및-검색-시작하기" tabindex="-1">1. 개요 및 검색 시작하기 <a class="header-anchor" href="#_1-개요-및-검색-시작하기" aria-label="Permalink to &quot;1. 개요 및 검색 시작하기&quot;">​</a></h2><p>협업이 누적될수록 과거의 의사결정 기록, 회의록, 업무 티켓, 첨부 문서를 찾는 데 많은 시간이 소요됩니다. IBS의 통합 검색 시스템은 개별 목록의 단순 필터를 넘어 시스템 전반의 텍스트와 첨부파일 정보를 한곳에서 탐색할 수 있도록 지원합니다.</p>',5)),(e(),i(A,null,{default:a(()=>[E(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%94%8D%20%EC%83%81%EB%8B%A8%20%EA%B2%80%EC%83%89%EC%B0%BD%20%EC%9E%85%EB%A0%A5%3Cbr%3E('%ED%86%B5%ED%95%A9%20%EA%B2%80%EC%83%89%20-%20%EC%97%85%EB%AC%B4%EA%B4%80%EB%A6%AC%EC%8B%9C%EC%8A%A4%ED%85%9C')%22%5D%20--%3E%20B%5B%22%E2%9A%A1%20%EC%A0%84%EC%B2%B4%EA%B2%80%EC%83%89%20%ED%8E%98%EC%9D%B4%EC%A7%80%20(%2Fwork%2Fsearch)%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22%E2%9A%99%EF%B8%8F%20%EA%B2%80%EC%83%89%20%EC%A1%B0%EA%B1%B4%20%EC%84%A4%EC%A0%95%22%7D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%8C%90%20%EB%B2%94%EC%9C%84%3A%20%EB%AA%A8%EB%93%A0%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%2F%20%EB%82%B4%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%22%F0%9F%97%82%EF%B8%8F%20%EB%8C%80%EC%83%81%3A%20%ED%9A%8C%EC%9D%98%EB%A1%9D%C2%B7%EC%97%85%EB%AC%B4%C2%B7%EB%8C%93%EA%B8%80%C2%B7%EA%B3%B5%EC%A7%80%C2%B7%EB%AC%B8%EC%84%9C%C2%B7%EA%B2%8C%EC%8B%9C%ED%8C%90%22%5D%0A%20%20%20%20C%20--%3E%20F%5B%22%F0%9F%8E%AF%20%EC%98%B5%EC%85%98%3A%20%EC%A0%9C%EB%AA%A9%EB%A7%8C%20%EC%B0%BE%EA%B8%B0%C2%B7%EC%97%B4%EB%A6%B0%20%EC%97%85%EB%AC%B4%EB%A7%8C%C2%B7%EC%B2%A8%EB%B6%80%ED%8C%8C%EC%9D%BC%22%5D%0A%20%20%20%20D%20%26%20E%20%26%20F%20--%3E%20G%5B%22%F0%9F%93%8A%20%EC%9C%A0%ED%98%95%EB%B3%84%20%EB%A7%9E%EC%B6%A4%20%EA%B2%80%EC%83%89%20%EA%B2%B0%EA%B3%BC%20%ED%91%9C%EC%B6%9C%20%26%20%EC%9B%90%ED%81%B4%EB%A6%AD%20%EC%9D%B4%EB%8F%99%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h3 id="🚀-검색-진입-방법" tabindex="-1">🚀 검색 진입 방법 <a class="header-anchor" href="#🚀-검색-진입-방법" aria-label="Permalink to &quot;🚀 검색 진입 방법&quot;">​</a></h3><ol><li><strong>상단 글로벌 검색창</strong>: 업무관리시스템 어디에서나 화면 상단 헤더의 <strong><code>[통합 검색 - 업무관리시스템]</code></strong> 입력창에 검색어를 입력하고 <code>Enter</code> 키 또는 <i class="mdi mdi-magnify"></i> 돋보기 아이콘을 클릭합니다.</li><li><strong>검색 전용 페이지 진입</strong>: 즉시 통합 검색 화면(<code>/work/search</code>)으로 전환되며, 입력한 키워드에 대한 검색 결과가 도메인별로 일목요연하게 표시됩니다.</li><li><strong>검색어 입력 기준</strong>: 보다 정확하고 신속한 색인을 위해 검색어는 <strong>최소 2자 이상</strong> 입력해야 합니다.</li></ol><hr><h2 id="_2-검색-범위-및-대상-설정" tabindex="-1">2. 검색 범위 및 대상 설정 <a class="header-anchor" href="#_2-검색-범위-및-대상-설정" aria-label="Permalink to &quot;2. 검색 범위 및 대상 설정&quot;">​</a></h2><p>통합 검색 화면에서는 검색 범위를 좁히거나 특정 유형의 데이터만 골라낼 수 있는 직관적인 필터 컨트롤을 제공합니다.</p><h3 id="🌐-검색-범위-워크스페이스-선택" tabindex="-1">🌐 검색 범위 (워크스페이스 선택) <a class="header-anchor" href="#🌐-검색-범위-워크스페이스-선택" aria-label="Permalink to &quot;🌐 검색 범위 (워크스페이스 선택)&quot;">​</a></h3><ul><li><strong>모든 워크스페이스</strong>: 사용자가 열람 권한을 가진 전체 워크스페이스를 대상으로 검색을 수행합니다. (타 사업지나 타 부서의 과거 사례/자료를 참조할 때 유용)</li><li><strong>내 워크스페이스</strong>: 현재 내가 멤버로 참여 중인 워크스페이스의 데이터만 한정하여 검색합니다.</li></ul><h3 id="🗂️-6대-검색-대상-선택" tabindex="-1">🗂️ 6대 검색 대상 선택 <a class="header-anchor" href="#🗂️-6대-검색-대상-선택" aria-label="Permalink to &quot;🗂️ 6대 검색 대상 선택&quot;">​</a></h3><p>검색 대상 체크박스를 통해 필요한 데이터 종류만 선택할 수 있습니다. 기본적으로 모든 대상이 활성화되어 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">대상 구분</th><th style="text-align:left;">검색 대상 필드 및 내용</th><th style="text-align:left;">주요 활용 상황</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>회의록</strong></td><td style="text-align:left;">회의 명칭, 안건(Agenda), 의결 결정 사항, 상세 내용</td><td style="text-align:left;">과거 회의 결정 배경 및 합의 사항 추적</td></tr><tr><td style="text-align:left;"><strong>업무</strong></td><td style="text-align:left;">업무 제목, 상세 설명(마크다운), 하위업무 내역</td><td style="text-align:left;">진행 중이거나 완료된 실무 과업 및 이슈 조회</td></tr><tr><td style="text-align:left;"><strong>댓글</strong></td><td style="text-align:left;">업무에 팀원들이 남긴 의견, 피드백, 변경 메모</td><td style="text-align:left;">업무 진행 과정에서 오고 간 구체적 대화 내용 추적</td></tr><tr><td style="text-align:left;"><strong>공지</strong></td><td style="text-align:left;">전사 또는 워크스페이스 공지 제목, 요약, 본문</td><td style="text-align:left;">주요 공지사항 및 운영 지침 검색</td></tr><tr><td style="text-align:left;"><strong>문서</strong></td><td style="text-align:left;">등록된 일반 문서 및 소송 관련 문서 제목, 문서 설명</td><td style="text-align:left;">계약서, 기안 양식, 제출용 증빙 문서 확인</td></tr><tr><td style="text-align:left;"><strong>게시판</strong></td><td style="text-align:left;">자유게시판/정보공유 게시글 제목 및 본문</td><td style="text-align:left;">사내 노하우 공유 및 질의응답 게시물 검색</td></tr></tbody></table><hr><h2 id="_3-상세-검색-옵션-활용" tabindex="-1">3. 상세 검색 옵션 활용 <a class="header-anchor" href="#_3-상세-검색-옵션-활용" aria-label="Permalink to &quot;3. 상세 검색 옵션 활용&quot;">​</a></h2><p>검색 폼의 <strong><code>[제목에서만 찾기]</code></strong> 체크박스와 <strong><code>[옵션]</code></strong> 토글을 열면 불필요한 검색 결과를 걸러내고 원하는 정보에 정확하게 도달할 수 있는 세부 제어 기능이 제공됩니다.</p><h3 id="🎯-제목에서만-찾기" tabindex="-1">🎯 제목에서만 찾기 <a class="header-anchor" href="#🎯-제목에서만-찾기" aria-label="Permalink to &quot;🎯 제목에서만 찾기&quot;">​</a></h3><ul><li>**<code>제목에서만 찾기</code>**를 체크하면 본문이나 설명 글을 제외하고, <strong>오직 제목/명칭에 검색어가 포함된 항목만</strong> 빠르게 추출합니다.</li><li>검색 결과가 너무 많아 핵심 문서나 업무 제목만 명확히 찾고 싶을 때 매우 유용합니다.</li></ul><h3 id="📂-옵션-접기-펼치기" tabindex="-1">📂 옵션 (접기/펼치기) <a class="header-anchor" href="#📂-옵션-접기-펼치기" aria-label="Permalink to &quot;📂 옵션 (접기/펼치기)&quot;">​</a></h3><p><code>옵션</code> 우측의 화살표를 클릭하여 확장하면 다음과 같은 추가 필터를 지정할 수 있습니다:</p><ol><li><strong>열린 업무만</strong>: <ul><li>이미 완료(Closed)된 업무를 제외하고, <strong>현재 진행 중이거나 처리가 필요한 열린(Open) 업무만</strong> 결과로 표시합니다.</li></ul></li><li><strong>첨부파일 검색 모드</strong>: <ul><li><strong>첨부파일은 검색하지 않음 (기본)</strong>: 텍스트 본문과 제목만 검색하여 가장 빠른 속도로 결과를 조회합니다.</li><li><strong>첨부파일명과 설명 검색</strong>: 업로드된 첨부파일의 파일명뿐만 아니라 파일 등록 시 함께 작성된 설명 문구까지 검색 대상에 포함합니다.</li><li><strong>첨부파일명만 검색</strong>: 등록된 첨부파일 중 파일 이름에 검색어가 포함된 항목을 검색합니다.</li></ul></li></ol><hr><h2 id="_4-검색-결과-확인-및-상세-이동" tabindex="-1">4. 검색 결과 확인 및 상세 이동 <a class="header-anchor" href="#_4-검색-결과-확인-및-상세-이동" aria-label="Permalink to &quot;4. 검색 결과 확인 및 상세 이동&quot;">​</a></h2><p>검색이 완료되면 상단에 <strong>총 일치 건수 배지</strong>가 표시되며, 그 아래로 유형별(회의록, 업무, 댓글, 공지, 문서, 게시판)로 그룹화된 결과 카드가 정렬됩니다.</p><ul><li><strong>원클릭 상세 이동</strong>: 검색된 각 항목의 제목이나 워크스페이스 링크를 클릭하면 해당 상세 페이지(업무 상세, 회의록 상세 등)로 즉시 이동합니다.</li><li><strong>본문 매칭 스니펫</strong>: 검색어가 포함된 본문 문맥이 카드 내에 요약 표시되어, 상세 화면에 들어가지 않고도 원하는 내용이 맞는지 직관적으로 판별할 수 있습니다.</li><li><strong>상태 및 메타정보 시각화</strong>: <ul><li><strong>업무</strong>: 업무 번호(#ID), 트래커 배지, 열림/닫힘 상태, 담당자 및 등록일</li><li><strong>회의록</strong>: 회의 상태(<code>준비</code>, <code>종료</code>, <code>취소</code>), 일시 및 장소</li><li><strong>첨부파일 아이콘</strong>: 파일이 첨부된 경우 클립 아이콘과 파일명이 함께 노출되어 증빙 유무를 즉시 파악 가능</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 실무 검색 팁</p><ul><li><strong>단축키 및 빠른 재검색</strong>: 검색창에서 단어를 입력한 뒤 마우스로 검색 버튼을 누를 필요 없이 키보드의 <code>Enter</code> 키를 누르면 즉시 검색이 실행됩니다.</li><li><strong>필터 조건 유지</strong>: 검색 대상이나 옵션을 변경한 후 <code>[검색]</code> 버튼을 다시 누르면 현재 입력된 검색어와 새로운 필터 조건이 결합된 결과를 즉시 갱신합니다.</li></ul></div><hr><h2 id="_5-데이터-보안-및-권한-격리-정책" tabindex="-1">5. 데이터 보안 및 권한 격리 정책 <a class="header-anchor" href="#_5-데이터-보안-및-권한-격리-정책" aria-label="Permalink to &quot;5. 데이터 보안 및 권한 격리 정책&quot;">​</a></h2><p>통합 검색은 시스템의 엄격한 역할 기반 보안 체계(Role-Based Access Control)와 완벽히 연동됩니다.</p><div class="important custom-block github-alert"><p class="custom-block-title">비공개 데이터의 보안 보호</p><p></p><ul><li><strong>비공개 워크스페이스</strong>: 사용자가 멤버로 등록되지 않은 비공개 워크스페이스의 데이터는 <strong>검색 결과에 일체 노출되지 않습니다.</strong></li><li><strong>비공개 업무 및 회의록</strong>: 비공개로 등록된 업무나 민감한 회의록은 <strong>작성자, 담당자 또는 해당 권한을 가진 관리자에게만</strong> 검색 결과로 표출됩니다.</li><li>본사 관리(<code>ibs_hq_manage</code>)의 보안 격리 대상 문서는 권한을 인가받은 임직원에게만 안전하게 제한 검색됩니다.</li></ul></div>',27))])}const b=r(C,[["render",c]]);export{f as __pageData,b as default};
